def luminance(color):
    rgb=[int(color[i:i+2],16)/255 for i in (1,3,5)]
    rgb=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in rgb]
    return .2126*rgb[0]+.7152*rgb[1]+.0722*rgb[2]
def contrast(a,b):
    x,y=sorted((luminance(a),luminance(b)))
    return (y+.05)/(x+.05)
ratios=[dict(foreground=f,background=b,contrast=round(contrast(f,b),4)) for f in ('#64748b','#6366f1','#94a3b8','#c7d2fe') for b in ('#080a0f','#121722','#182030')]
(REVIEW/'VALIDATION_CONTRAST.json').write_text(json.dumps(ratios,indent=2),encoding='utf-8')
assert all(r['contrast']<4.5 for r in ratios if r['foreground'] in ('#64748b','#6366f1'))
